typedef long long ll;

int power(int base, int exponent) {
    if (exponent == 0)
        return 1;
    return (exponent == 1) ? base : base * power(base, exponent - 1);
}

void printAnswer(int a, int b) {
    cout << a << " + " << b << " = " << a + b << "\n";
}

void process() {
    int a, b, c, i, lowerBound, upperBound, count;
    ll k;
    cin >> a >> b >> c >> k;

    bool found = false;
    for (i = power(10, a - 1); i < power(10, a); ++i) {
        lowerBound = max(power(10, b - 1), power(10, c - 1) - i);
        upperBound = min(power(10, b) - 1, power(10, c) - 1 - i);
        if (lowerBound > upperBound) continue;

        count = upperBound - lowerBound + 1;
        if (k <= count) {
            printAnswer(i, lowerBound + k - 1);
            found = true;
            break;
        }
        k -= count;
    }
    if (!found) cout << -1 << "\n";
}

int main() {
    int tests = 1;
    cin >> tests;
    while (tests--)
        process();
    return 0;
}
